contract.head:
#version 300 es
precision highp float;
uniform vec2 u_res;
uniform float u_dpr;
uniform vec3 u_pal[6];
uniform float u_dark;
uniform float u_grain;
uniform float u_opt;
out vec4 o;

contract.lib:
const float PI = 3.14159265;
float sat(float x){ return clamp(x, 0., 1.); }
float s01(float a, float b, float x){ return smoothstep(a, b, x); }
float pxu(){ return 2./u_res.y; }
float cssu(){ return 2.*u_dpr/u_res.y; }
mat2 rot(float a){ float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }
float h21(vec2 p){ vec3 q = fract(vec3(p.xyx)*.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y)*q.z); }
vec2 h22(vec2 p){ vec3 q = fract(vec3(p.xyx)*vec3(.1031, .1030, .0973)); q += dot(q, q.yzx + 33.33); return fract((q.xx + q.yz)*q.zy); }
float gn(vec2 p){
  vec2 i = floor(p), f = p - i;   // not fract(p): on an exact integer the two can disagree and a whole row jumps a cell
  vec2 u = f*f*f*(f*(f*6. - 15.) + 10.);
  float a = dot(h22(i)*2. - 1., f);
  float b = dot(h22(i + vec2(1., 0.))*2. - 1., f - vec2(1., 0.));
  float c = dot(h22(i + vec2(0., 1.))*2. - 1., f - vec2(0., 1.));
  float d = dot(h22(i + vec2(1., 1.))*2. - 1., f - vec2(1., 1.));
  return 1.6*mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm(vec2 p){ float s = 0., a = .5; for (int i = 0; i < 5; i++) { s += a*gn(p); p = mat2(1.6, 1.2, -1.2, 1.6)*p + vec2(1.7, 9.2); a *= .5; } return s; }
float fbm3(vec2 p){ float s = 0., a = .5; for (int i = 0; i < 3; i++) { s += a*gn(p); p = mat2(1.6, 1.2, -1.2, 1.6)*p + vec2(1.7, 9.2); a *= .5; } return s; }
float sm1(float x){ x = sat(x); return mix(x, x*x*(3. - 2.*x), .6); }
vec3 ramp(float t){ t = sat(t)*4.; vec3 c = mix(u_pal[0], u_pal[1], sm1(t)); c = mix(c, u_pal[2], sm1(t - 1.)); c = mix(c, u_pal[3], sm1(t - 2.)); return mix(c, u_pal[4], sm1(t - 3.)); }
vec3 dim(vec3 c, float k){ return vec3(c.x*(1. - k), c.yz*(1. - .3*k)); }
vec3 lift(vec3 c, float k){ return vec3(c.x + k, c.yz*(1. - .6*sat(k*2.))); }
float cover(float d){ float w = pxu(); return 1. - smoothstep(-w, w, d); }
float sdBox(vec2 p, vec2 b, float r){ vec2 q = abs(p) - b + r; return length(max(q, 0.)) + min(max(q.x, q.y), 0.) - r; }

wallpapers.src:
float rEdge(float x, float i){
  return .8 - i*.3 + .15*sin(x*.95 + i*1.9 + .4) + .085*sin(x*2.1 - i*2.7 + 1.3) + .03*gn(vec2(x*1.3 + i*7.1, i*3.3));
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], u_pal[0], sat(.55 - p.y*.45));
  float soft = mix(.035, .15, u_opt);
  for (int k = 0; k < 7; k++) {
    float i = float(k);
    float e = .01;
    float y = rEdge(p.x, i);
    float sl = (rEdge(p.x + e, i) - rEdge(p.x - e, i))/(2.*e);
    float d = (p.y - y)/sqrt(1. + sl*sl);
    float a = cover(d);
    col = dim(col, mix(.38, .55, u_dark)*exp(-max(d, 0.)/soft)*(1. - a));
    vec3 c = ramp(i/6. + .05*sin(p.x*.8 + i*2.));
    float dep = max(-d, 0.);
    c = dim(c, .34*s01(0., .5, dep));
    c.x += .075*exp(-dep/.03) + .03*exp(-dep/.12);
    col = mix(col, c, a);
  }
  col.x += .035*s01(1.8, -1.2, p.x - p.y*.6);
  return col;
}

vec3 wall(vec2 p){
  vec2 O = vec2(-2.05, -1.5);
  vec3 col = mix(u_pal[5], dim(u_pal[5], .35), sat(length(p - vec2(1.3, .9))*.42));
  float step_ = mix(.118, .158, u_opt);
  for (int k = 0; k < 10; k++) {
    float i = float(k);
    float th = .1 + i*step_;
    vec2 q = rot(-th)*(p - O);
    q.y -= .045*q.x*q.x - .12*q.x;
    float Lp = 4.5 + .35*sin(i*1.7);
    float s = q.x/Lp;
    float w = (.4 + .05*sin(i*2.3))*pow(sat(sin(PI*sat(s))), .62);
    float d = max(abs(q.y) - w, max(-q.x, q.x - Lp));
    vec2 qs = rot(-th)*(p - O - vec2(.045, -.06));
    qs.y -= .045*qs.x*qs.x - .12*qs.x;
    float ws = (.4 + .05*sin(i*2.3))*pow(sat(sin(PI*sat(qs.x/Lp))), .62);
    float sh = 1. - s01(-.05, .11, abs(qs.y) - ws);
    float a = cover(d*.85);
    col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
    float ny = clamp(q.y/max(w, 1e-3), -1.2, 1.2);
    vec3 c = ramp(i/9. + .1*(s - .5));
    c = dim(c, .3*(1. - s01(.25, .75, s)));
    c.x += .05*ny - .04*ny*ny;
    float edge = max(w - abs(q.y), 0.);
    c.x += (ny > 0. ? .06 : .02)*exp(-edge/.012);
    c.x += .03*exp(-edge/.07);
    col = mix(col, c, a);
  }
  return col;
}

vec3 bgP(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .32*p.x - .3*p.y));
  c = mix(c, u_pal[5], .55*s01(-.25, -1.15, p.y));
  vec2 oc = vec2(.38, .12);
  float r = length(p - oc);
  c = mix(c, u_pal[4], .65*exp(-r*r*1.5));
  vec3 orb = mix(u_pal[3], u_pal[2], sm1(r/.58));
  orb.x += .06*s01(.55, .0, length(p - oc - vec2(-.16, .2)));
  c = mix(c, orb, 1. - s01(.5, .64, r));
  float r2 = length(p - vec2(-.82, -.42));
  c = mix(c, mix(u_pal[4], u_pal[2], sm1(r2/.3)), (1. - s01(.22, .34, r2))*.9);
  return c;
}
vec3 wall(vec2 p){
  float fw = mix(.035, .12, u_opt);
  float fx = p.x/fw;
  float cx = (floor(fx) + .5)*fw;
  float f = fract(fx) - .5;
  float xs = cx - 1.6*fw*sin(f*PI);
  vec3 acc = vec3(0.);
  for (int j = 0; j < 6; j++) {
    float a = float(j)*1.047 + .3;
    acc += bgP(vec2(xs, p.y) + vec2(.04, .025)*vec2(cos(a), sin(a)));
  }
  vec3 c = acc/6.;
  float hl = exp(-pow((f + .27)/.07, 2.));
  float seam = exp(-(.5 - abs(f))/.018);
  c.x += .03*hl - .03*seam + .03*cos(f*PI) - .015;
  c.yz *= 1. - .2*hl;
  return c;
}

float ridgeS(float x, float i){
  float s = 0., a = .5, f = 1.;
  for (int o = 0; o < 5; o++) {
    s += a*(1. - abs(gn(vec2(x*f + i*13.7, i*5.3 + float(o)*3.1))));
    f *= 2.07; a *= .47;
  }
  return s;
}
vec3 wall(vec2 p){
  float hz = -.12;
  float t = sat((p.y - hz)/1.15);
  vec3 sky = mix(u_pal[0], u_pal[1], sm1(t*2.4));
  sky = mix(sky, u_pal[2], sm1(t*2. - .6));
  sky = mix(sky, u_pal[3], sm1(t*1.7 - .75));
  vec2 sp = vec2(.42, hz + .17);
  float sr = length(p - sp);
  sky = mix(sky, u_pal[4], .5*exp(-sr*2.2) + .3*exp(-sr*8.));
  vec3 col = mix(sky, lift(u_pal[4], .02), cover(sr - .085));
  float hzA = mix(.45, 1., u_opt);
  for (int k = 0; k < 5; k++) {
    float i = float(k);
    float base = hz + .2 - i*.2;
    float amp = .2 + i*.06;
    float sc = .5 + i*.08;
    float e = .006;
    float y = base + amp*(ridgeS(p.x*sc, i) - .62);
    float y2 = base + amp*(ridgeS((p.x + e)*sc, i) - .62);
    float sl = (y2 - y)/e;
    float a = cover((p.y - y)/sqrt(1. + sl*sl));
    float far = 1. - i/4.;
    float u = i/4.;
    vec3 m = mix(mix(u_pal[0], u_pal[1], .55), u_pal[1], sm1(u*2.));
    m = mix(m, u_pal[2], sm1(u*2. - .6));
    m = mix(m, u_pal[5], sm1(u*1.6 - .55));
    m = dim(m, .18 + .12*u);
    m = mix(m, u_pal[0], far*far*hzA*.55);
    m = mix(m, u_pal[4], .28*far*exp(-length(p - sp)*1.2));
    float dep = max(y - p.y, 0.);
    m = mix(m, mix(u_pal[0], u_pal[1], .6), hzA*.38*s01(.0, .3, dep)*(.3 + .7*far));
    m.x += .08*exp(-dep/.007)*exp(-abs(p.x - sp.x)*.8)*(.35 + .65*far);
    col = mix(col, m, a);
  }
  return col;
}

float curtainB(vec2 p, float seed, float yb, float h){
  float c = yb + .2*sin(p.x*.9 + seed) + .12*sin(p.x*2.1 + seed*2.3) + .05*gn(vec2(p.x*2.6, seed));
  float up = p.y - c;
  float wx = p.x + .2*up*sin(p.x*1.3 + seed);
  float r = .5 + .5*gn(vec2(wx*9. + 2.2*gn(vec2(wx*1.3, seed + 4.)), up*.3 + seed*2.));
  float env = s01(-.3, .5, gn(vec2(p.x*.6 + seed*3., seed)));
  float core = (up > 0. ? exp(-up/h) : exp(up/.03))*(.15 + .85*r*r*r)*(1. + .9*exp(-max(up, 0.)/.04));
  float glow = exp(-abs(up - .12)/.32)*.3;
  return (core*1.9 + glow)*env;
}
vec3 skyB(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[5], s01(-.45, 1., p.y));
  vec2 cell = floor(p/.045);
  vec2 sp = (cell + .2 + .6*h22(cell))*.045;
  float sz = max(.0011, cssu()*.45)*(.6 + 1.1*h21(cell + 3.1));
  float on = step(.78, h21(cell + 9.7));
  c.x += .5*on*exp(-dot(p - sp, p - sp)/(sz*sz))*u_dark*s01(-.25, .5, p.y);
  float k = mix(.7, 1.5, u_opt);
  float i1 = curtainB(p, 1.3, .02, .34)*k;
  float i2 = curtainB(p*vec2(1.2, 1.) + vec2(2.3, 0.), 7.9, .36, .3)*k*.75;
  vec3 a1 = mix(u_pal[1], u_pal[2], s01(.0, .65, p.y + .02));
  vec3 a2 = mix(u_pal[3], u_pal[2], s01(.25, .85, p.y));
  c = mix(c, a1, sat(i1*1.1));
  c = mix(c, a2, sat(i2));
  c.x += .12*sat(i1 + i2)*u_dark;
  c = mix(c, u_pal[1], .12*k*exp(-abs(p.y + .3)*3.5));
  return c;
}
float ridgeB(float x){
  float s = 0., a = .5, f = 1.;
  for (int o = 0; o < 4; o++) { s += a*(1. - abs(gn(vec2(x*f*.8 + 4.1, float(o)*2.3)))); f *= 2.1; a *= .5; }
  return -.43 + .2*s - .05*x*x*.1;
}
vec3 sceneB(vec2 p){
  vec3 c = skyB(p);
  float d = p.y - ridgeB(p.x);
  vec3 m = mix(u_pal[4], u_pal[0], .3*s01(-.15, 0., d));
  m.x += .05*exp(-abs(d)/.006)*u_dark;
  return mix(c, m, cover(d));
}
vec3 wall(vec2 p){
  float lake = -.45;
  vec3 c = sceneB(p);
  if (p.y < lake + .01) {
    float w = .006*gn(vec2(p.x*3., p.y*55.)) + .004*gn(vec2(p.x*9., p.y*120.));
    vec2 rp = vec2(p.x + w, 2.*lake - p.y + w*2.);
    vec3 r = dim(sceneB(rp), mix(.1, .28, u_dark));
    r = mix(r, u_pal[4], mix(.15, .3, u_dark)*s01(lake, lake - .55, p.y));
    c = mix(c, r, cover(p.y - lake));
  }
  return c;
}

float hS(vec2 p){
  vec2 q = rot(.35)*p;
  q += .28*vec2(sin(q.y*1.3 + .5), sin(q.x*1.1 + 1.7));
  float w = 1.6*sin(q.y*1.1 + .4) + .8*sin(q.y*2.3 - q.x*.5);
  return .5*sin(q.x*3.4 + w) + .25*sin(q.x*6.1 + 1.3*w - q.y*1.1) + .2*sin(q.y*2.9 + q.x*1.2);
}
vec3 wall(vec2 p){
  float e = .003, amp = mix(.3, .75, u_opt);
  float h0 = hS(p), hx = hS(p + vec2(e, 0.)), hy = hS(p + vec2(0., e));
  vec3 n = normalize(vec3(-(hx - h0)/e*amp, -(hy - h0)/e*amp, 1.));
  vec3 Ld = normalize(vec3(-.5, .62, .6));
  float dif = dot(n, Ld);
  vec3 H = normalize(Ld + vec3(0., 0., 1.));
  float nh = clamp(dot(n, H), 0., 1.);
  float t = .5 + .45*sin(p.x*.55 - p.y*.4 + h0*.5);
  vec3 c = ramp(t);
  c.yz = rot(n.x*.9 - n.y*.5)*c.yz;
  float occ = sat(dif*.9 + .1);
  c = mix(c, u_pal[5], .7*(1. - occ)*(1. - occ));
  c.x *= .78 + .3*occ;
  c.x += .16*pow(nh, 26.) + .12*pow(nh, 160.);
  c.yz *= 1. - .4*pow(nh, 26.);
  return c;
}

vec3 studio(vec2 p){
  float t = s01(-.42, .2, p.y + .04*p.x);
  vec3 fl = mix(lift(u_pal[5], .035), u_pal[5], s01(-1., -.25, p.y));
  vec3 wl = mix(u_pal[5], dim(u_pal[5], .28), s01(-.1, 1.1, p.y));
  vec3 c = mix(fl, wl, t);
  c.x += .055*exp(-dot(p - vec2(-.55, .15), p - vec2(-.55, .15))*.3) - .035*s01(.4, 1.8, p.x);
  return c;
}
void ball(inout vec3 col, vec2 p, vec2 g, float r, vec3 bc, float bl){
  vec2 c = g + vec2(0., r);
  vec2 q = (p - c)/r;
  float d = length(p - c) - r;
  float aa = pxu()*1.3 + bl;
  float a = 1. - smoothstep(-aa, aa, d);
  vec2 sq = (p - g - vec2(.62*r, .2*r))/vec2(1.35*r, .36*r);
  float soft = exp(-dot(sq, sq)*1.2);
  vec2 cq = (p - g - vec2(.08*r, 0.))/vec2(.62*r, .1*r);
  float cont = exp(-dot(cq, cq)*1.5);
  col = dim(col, (mix(.26, .4, u_dark)*soft + mix(.42, .55, u_dark)*cont)*(1. - a));
  vec2 bq = (p - g)/vec2(1.3*r, .35*r);
  col.yz = mix(col.yz, bc.yz, .22*exp(-dot(bq, bq))*(1. - a));
  float z = sqrt(max(1. - dot(q, q), 0.));
  vec3 n = normalize(vec3(q, z + .002));
  vec3 K = normalize(vec3(-.62, .55, .56)), F = normalize(vec3(.85, .05, .5));
  float kw = sat(dot(n, K)*.62 + .38);
  kw = kw*kw*(3. - 2.*kw);
  float fw = sat(dot(n, F))*.2;
  float bo = sat(-n.y)*.22;
  vec3 b = vec3(bc.x*(.34 + .64*kw + fw + .25*bo), bc.yz*(1. + .55*kw*(1. - kw) + .12*(1. - kw) - .18*kw*kw));
  b.x += .045*(1. - kw)*pow(1. - z, 1.5);
  b = mix(b, studio(vec2(p.x, g.y - .1)), .22*bo);
  vec3 R = vec3(2.*n.z*n.x, 2.*n.z*n.y, 2.*n.z*n.z - 1.);
  float gl = mix(.3, 1., u_opt);
  vec3 env = mix(dim(u_pal[5], .15), lift(u_pal[5], .1), s01(-.25, .25, R.y));
  float fr = pow(1. - z, 3.);
  b = mix(b, env, (.08 + .42*gl)*fr);
  float box = sdBox(R.xy - vec2(-.44, .42), vec2(.24, .16), .13);
  float sb = (1. - s01(-.14, .12, box))*s01(-.1, .35, R.z);
  b = mix(b, vec3(min(b.x + .3, .975), b.yz*.5), sb*gl*.7);
  float fb = (1. - s01(-.1, .1, sdBox(R.xy - vec2(.62, .02), vec2(.05, .2), .05)))*s01(-.1, .3, R.z);
  b.x += .06*fb*gl;
  col = mix(col, b, a);
}
vec3 wall(vec2 p){
  vec3 col = studio(p);
  ball(col, p, vec2(1.08, -.1), .11, u_pal[4], .006);
  ball(col, p, vec2(-.1, -.16), .17, u_pal[3], .004);
  ball(col, p, vec2(-1.08, -.36), .31, u_pal[1], .002);
  ball(col, p, vec2(.6, -.62), .46, u_pal[0], 0.);
  ball(col, p, vec2(-.42, -.9), .29, u_pal[2], .003);
  ball(col, p, vec2(1.45, -.96), .25, u_pal[4], .005);
  return col;
}

float shoreL(float x){ return -.5 + .22*sin(x*.8 + .6) + .1*sin(x*1.9 - 1.) + .04*gn(vec2(x*2.5, 3.)); }
vec3 wall(vec2 p){
  float sy = shoreL(p.x);
  float up = p.y - sy;
  float D = .84 - .62*sat(up*.75) + .16*fbm(p*.9 + vec2(3., 1.)) - .1*s01(.5, 1.6, up);
  vec3 c = ramp(sat(D*1.12 - .05));
  float reef = s01(.12, .35, fbm(p*1.6 + 9.))*s01(.2, .5, up)*s01(1.5, .7, up);
  c = dim(c, .22*reef);
  c.yz = mix(c.yz, u_pal[1].yz, .25*reef);
  vec2 q = p*vec2(.9, 1.15);
  vec2 w = q*3.4 + .9*vec2(gn(q*1.3), gn(q*1.3 + 5.2));
  float ca = exp(-abs(gn(w))*9.) + .6*exp(-abs(gn(w*1.65 + 2.3))*11.);
  float shal = s01(.35, .85, D)*s01(-.01, .04, up);
  c.x += mix(.03, .12, u_opt)*ca*shal;
  c.yz *= 1. - .2*ca*shal*u_opt;
  float edge = up + .012*gn(vec2(p.x*9., 1.));
  float sand = cover(edge);
  vec3 sd = u_pal[4];
  sd.x += .02*gn(p*7.) - .06*s01(-.08, 0., edge);
  sd = mix(sd, dim(u_pal[3], .15), .4*s01(-.06, 0., edge));
  c = mix(c, sd, sand);
  float foam = exp(-abs(edge - .006)/.006) + .55*exp(-abs(edge - .055 - .01*gn(vec2(p.x*4., 7.)))/.007) + .3*exp(-abs(edge - .12 - .02*gn(vec2(p.x*3., 2.)))/.008);
  foam *= .55 + .45*gn(p*vec2(18., 40.));
  c = mix(c, u_pal[5], sat(foam)*.75*(1. - sand));
  return c;
}

vec3 wall(vec2 p){
  vec2 O = vec2(.0, -1.32);
  vec2 q = p - O;
  float r = length(q);
  float a = atan(q.x, q.y);
  float N = mix(5., 9., u_opt);
  float s = (a + .1*r)*N/PI*2.;
  float x = cos(s*PI);
  float ws = pxu()*N*2./max(r, .05);
  float fold = x/(abs(x) + .035 + ws*2.5);
  vec3 c = ramp(.5 + a*.37 + .03*r);
  c = dim(c, .26*s01(.3, 2.6, r));
  c.x += .055*fold*(1. - .4*exp(-r)) - .015*(1. - abs(fold));
  c.yz *= 1. - .1*fold;
  float g = exp(-r*1.15);
  c = mix(c, u_pal[5], .8*g*g + .25*g);
  return c;
}

vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], .05), dim(u_pal[5], .35), sat(.42 - p.y*.3 + p.x*.1));
  col.x += .03*fbm3(p*1.6)*u_dark;
  vec2 P0 = vec2(-.62, .3);
  vec2 dIn = normalize(P0 - vec2(-2.2, .95));
  vec2 v = p - P0;
  float along = dot(v, dIn), across = dot(v, vec2(-dIn.y, dIn.x));
  float Iin = exp(-across*across/(.0007 + .0004*u_opt))*s01(.04, -.08, along);
  float ang = atan(v.y, v.x);
  float spread = mix(.35, .75, u_opt);
  float a0 = -.2 - spread;
  float t = (ang - a0)/spread;
  float r = length(v);
  float soft = .025 + .05/(1. + r*3.);
  float fan = s01(-soft*4., soft*4., t)*s01(1. + soft*4., 1. - soft*4., t)*s01(.0, .25, r);
  float haze = .6 + .4*fbm3(vec2(ang*14., r*1.1 + 3.));
  float I = fan*haze*exp(-r*.32);
  float bloom = s01(-.6, .5, t)*s01(1.6, .5, t)*exp(-r*.5)*.22;
  col = mix(col, ramp(sat(t)), sat(bloom));
  col = mix(col, ramp(sat(t)), sat(I*1.5));
  col.x += .14*I*u_dark;
  col = mix(col, lift(u_pal[2], .2), sat(Iin*.9));
  col.x += mix(.12, .25, u_dark)*exp(-r*r*120.);
  return col;
}

float hillM(float x, float i){
  return -.02 - i*.2 + (.1 + .03*i)*sin(x*(.9 + .25*i) + i*2.1) + .06*sin(x*(2.1 + .3*i) - i*1.3) + .012*gn(vec2(x*3., i*7.));
}
vec3 wall(vec2 p){
  vec3 sky = mix(u_pal[1], u_pal[0], sm1((p.y + .1)/1.1));
  vec2 sp = vec2(-.75, .3);
  float sr = length(p - sp);
  sky = mix(sky, u_pal[5], .6*exp(-sr*1.7));
  vec3 col = sky;
  float haze = mix(.35, .9, u_opt);
  for (int k = 0; k < 5; k++) {
    float i = float(k);
    float e = .01;
    float y = hillM(p.x, i);
    float sl = (hillM(p.x + e, i) - y)/e;
    float a = cover((p.y - y)/sqrt(1. + sl*sl));
    float u = i/4.;
    vec3 m = mix(u_pal[2], u_pal[3], sm1(u*2.));
    m = mix(m, u_pal[4], sm1(u*2. - 1.));
    m = mix(m, u_pal[1], (1. - u)*(1. - u)*haze*.8);
    m = mix(m, u_pal[5], .22*(1. - u)*exp(-length(p - sp)*1.3));
    m.x += .045*clamp(sl*.9, -1., 1.)*(.35 + .65*u);
    float dep = max(y - p.y, 0.);
    m = dim(m, .12*s01(.0, .35, dep)*(.5 + u));
    m.x += .05*exp(-dep/.018)*(1. - u*.4);
    m.x += .01*u*gn(p*vec2(28., 80.));
    col = mix(col, m, a);
  }
  return col;
}

float duneH(vec2 q){
  vec2 w = q + .8*vec2(gn(q*.18 + 3.), gn(q*.18 + 8.));
  float r1 = 1. - abs(gn(w*vec2(.42, .3)));
  float r2 = 1. - abs(gn(w*vec2(.9, .7) + 5.));
  return r1*r1*.9 + r2*r2*.25;
}
vec3 wall(vec2 p){
  float hz = .3;
  vec3 sky = mix(u_pal[4], u_pal[5], sm1((p.y - hz)/(1. - hz)*1.3));
  vec2 sp = vec2(-1.05, hz + .12);
  sky = mix(sky, lift(u_pal[3], .04), .5*exp(-length((p - sp)*vec2(.6, 1.))*3.));
  if (p.y > hz + .003) return sky;
  float z = .6/(hz - p.y + .01);
  vec2 q = vec2(p.x*z, z*1.6);
  float e = .015 + .004*z;
  float h = duneH(q), hx = duneH(q + vec2(e, 0.)), hz2 = duneH(q + vec2(0., e));
  vec3 n = normalize(vec3(-(hx - h)/e*.9, 1., -(hz2 - h)/e*.9));
  float el = mix(.15, .6, u_opt);
  vec3 L = normalize(vec3(-.9, el, .35));
  float dif = dot(n, L);
  float t = sat(dif*1.15 + .1);
  vec3 c = mix(u_pal[0], u_pal[1], sm1(t*3.));
  c = mix(c, u_pal[2], sm1(t*3. - 1.));
  c = mix(c, u_pal[3], sm1(t*3. - 2.));
  c.x += .012*gn(vec2(q.x*14., q.y*5.))*exp(-z*.3);
  float fog = 1. - exp(-z*.06);
  c = mix(c, u_pal[4], fog);
  return mix(c, sky, s01(hz - .004, hz + .003, p.y));
}

vec3 fieldF(vec2 p, float b){
  vec3 c = mix(u_pal[5], dim(u_pal[5], .12), sat(.5 - p.y*.3));
  float k = 1./(1. + b*2.2);
  vec2 d0 = p - vec2(-.95, .42), d1 = p - vec2(.75, .62), d2 = p - vec2(.18, -.58), d3 = p - vec2(1.3, -.45);
  c = mix(c, u_pal[0], .92*exp(-dot(d0, d0)*1.7*k));
  c = mix(c, u_pal[1], .88*exp(-dot(d1, d1)*2.1*k));
  c = mix(c, u_pal[2], .88*exp(-dot(d2, d2)*1.9*k));
  c = mix(c, u_pal[3], .75*exp(-dot(d3, d3)*2.8*k));
  return c;
}
void pane(inout vec3 col, vec2 p, vec2 c, vec2 hs, float r, float ang, float lvl){
  vec2 q = rot(-ang)*(p - c);
  float d = sdBox(q, hs, r);
  vec2 qs = rot(-ang)*(p - c - vec2(.035, -.07));
  float sh = 1. - s01(-.1, .18, sdBox(qs, hs, r));
  float a = cover(d);
  col = dim(col, mix(.2, .32, u_dark)*sh*(1. - a));
  float e = .003;
  vec2 gr = vec2(sdBox(q + vec2(e, 0.), hs, r) - d, sdBox(q + vec2(0., e), hs, r) - d)/e;
  vec2 n = rot(ang)*gr;
  float rim = exp(min(d, 0.)/.06);
  float fr = mix(.3, 1., u_opt);
  vec3 g = mix(fieldF(p - n*.07*rim, fr*(.7 + lvl*.4)), col, .25);
  g = lift(g, mix(.035, .07, u_opt) + .02*lvl);
  g.x += .025*(q.y/hs.y);
  float lit = dot(n, normalize(vec2(-.6, .8)));
  float band = exp(min(d, 0.)/.005);
  g.x += band*(.1 + .22*max(lit, 0.)) + .045*exp(min(d, 0.)/.035)*max(lit, 0.);
  g.x -= band*.05*max(-lit, 0.);
  g.x += .01*fr*gn(p/cssu()*.4);
  col = mix(col, g, a);
}
vec3 wall(vec2 p){
  vec3 col = fieldF(p, 0.);
  pane(col, p, vec2(-.68, -.3), vec2(.4, .4), .4, 0., 0.);
  pane(col, p, vec2(.42, .06), vec2(.62, .48), .17, .12, 1.);
  pane(col, p, vec2(1.12, .66), vec2(.3, .11), .11, -.18, .5);
  return col;
}

float ribY(float x, float i){
  return -.8 + i*.47 + (.2 + .05*i)*sin(x*(.72 + .1*i) + i*1.9 + .3) + .08*sin(x*1.55 - i*2.4);
}
vec3 wall(vec2 p){
  vec3 col = mix(lift(u_pal[5], .03), dim(u_pal[5], .3), sat(.55 - .3*p.y + .12*p.x));
  col = mix(col, u_pal[2], .25*exp(-dot(p - vec2(-.6, .5), p - vec2(-.6, .5))*.5));
  float gl = mix(.25, 1., u_opt);
  vec3 K = normalize(vec3(-.35, .72, .6));
  vec3 H = normalize(K + vec3(0., 0., 1.));
  for (int k = 0; k < 4; k++) {
    float i = float(k);
    float e = .01;
    float y = ribY(p.x, i);
    float sl = (ribY(p.x + e, i) - y)/e;
    float nr = sqrt(1. + sl*sl);
    float w = .21 + .04*sin(p.x*.8 + i*3.1);
    float d = (p.y - y)/nr;
    float ds = (p.y + .06 - ribY(p.x - .04, i))/nr;
    float sh = 1. - s01(w*.55, w + .2, abs(ds));
    float a = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, abs(d) - w);
    col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
    float v = clamp(d/w, -1., 1.);
    vec2 ac = vec2(-sl, 1.)/nr;
    vec3 n = normalize(vec3(ac*v, sqrt(max(1. - v*v, 0.)) + .02));
    float kw = sat(dot(n, K)*.62 + .38);
    kw = kw*kw*(3. - 2.*kw);
    vec3 c = mix(u_pal[k], u_pal[k + 1], .5 + .5*sin(p.x*.55 + i*1.7));
    c = vec3(c.x*(.5 + .56*kw), c.yz*(1. + .5*kw*(1. - kw) - .1*kw*kw));
    c.x += .05*sat(-v)*(1. - kw)*s01(.4, 1., abs(v));
    float nh = sat(dot(n, H));
    c.x += gl*(.16*pow(nh, 40.) + .05*pow(nh, 6.));
    c.yz *= 1. - .4*gl*pow(nh, 40.);
    col = mix(col, c, a);
  }
  return col;
}

void sheet(inout vec3 col, vec2 p, vec2 C, float Rad, float R, vec3 face){
  float u = length(p - C) - Rad;
  vec2 dir = (p - C)/max(length(p - C), 1e-4);
  float lit = dot(-dir, normalize(vec2(-.5, .8)));
  float sh = exp(-max(u, 0.)/(.45*R + .05))*s01(-.03, .005, u)*(.65 - .35*lit);
  float a = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, u);
  col = dim(col, mix(.3, .42, u_dark)*sh*(1. - a));
  vec3 c = face;
  c.x += .035*s01(.0, -1.6, u) - .02 - .03*dot(p, normalize(vec2(.6, -.8)))*.4;
  c.x += .004*gn(p/cssu()*.3);
  float ui = u + 2.*R;
  c = dim(c, .22*exp(-max(-ui, 0.)/.07)*s01(.0, -.004, ui));
  float s = clamp((u + R)/R, -1., 1.);
  float inR = 1. - smoothstep(-pxu()*1.2, pxu()*1.2, abs(u + R) - R);
  vec3 n = normalize(vec3(-dir*s, sqrt(max(1. - s*s, 0.)) + .02));
  float kw = sat(dot(n, normalize(vec3(-.45, .65, .6)))*.6 + .4);
  kw = kw*kw*(3. - 2.*kw);
  vec3 b = mix(face, u_pal[4], .55);
  b = vec3(b.x*(.62 + .45*kw), b.yz*(1. + .3*(1. - kw)));
  b.x += .07*pow(sat(dot(n, normalize(vec3(-.3, .5, .81)))), 18.);
  c = mix(c, b, inR);
  col = mix(col, c, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[0], dim(u_pal[0], .25), sat(.5 - .3*p.y + .2*p.x));
  col.x += .003*gn(p/cssu()*.3);
  float R = mix(.04, .13, u_opt);
  sheet(col, p, vec2(-2.7, -2.5), 3.25, R*1.1, u_pal[1]);
  sheet(col, p, vec2(3.0, 2.6), 3.05, R, u_pal[2]);
  sheet(col, p, vec2(2.9, -2.3), 2.25, R*.85, u_pal[3]);
  return col;
}

float drop(vec2 p, vec2 c, float R, float k){
  float r = length(p - c);
  float x = r - R;
  return (sin(x*k)*exp(-x*x*16.) + .45*sin((r - R*.6)*k*1.15)*exp(-pow(r - R*.6, 2.)*30.))*exp(-r*.8);
}
float hR(vec2 p){
  return drop(p, vec2(.6, .18), .62, 34.) + .8*drop(p, vec2(-.85, -.38), .45, 40.) + .6*drop(p, vec2(.05, -.82), .3, 46.) + .05*gn(p*1.5);
}
vec3 wall(vec2 p){
  float e = .002;
  float A = mix(.0015, .006, u_opt);
  float h = hR(p);
  vec2 g = vec2(hR(p + vec2(e, 0.)) - h, hR(p + vec2(0., e)) - h)/e*A;
  float t = .5 + .14*(p.x + g.x*14.) - .16*(p.y + g.y*14.);
  vec3 c = ramp(t);
  vec3 n = normalize(vec3(-g*3., 1.));
  float sp = pow(sat(dot(n, normalize(vec3(-.4, .5, .77)))), 60.);
  c = mix(c, u_pal[5], sat(sp*.6));
  c.x += .05*(n.y - n.x)*2.;
  return c;
}

float hC(vec2 p){ return fbm3(p*.42 + vec2(2., 7.))*1.1 + .08*gn(p*1.7) + .22*sin(p.x*.6 + 1.); }
vec3 wall(vec2 p){
  float e = .003;
  float h = hC(p);
  vec2 g = vec2(hC(p + vec2(e, 0.)) - h, hC(p + vec2(0., e)) - h)/e;
  vec3 c = ramp(sat(h*.62 + .5));
  vec3 n = normalize(vec3(-g*.5, 1.));
  c.x += .07*(dot(n, normalize(vec3(-.6, .7, .55))) - .72);
  float st = .07;
  float v = h/st;
  float dl = abs(fract(v + .5) - .5)*st/max(length(g), .02);
  float major = step(4.5, mod(floor(v + .5) + 50., 5.));
  float lw = cssu()*(.55 + .6*major);
  float line = 1. - s01(lw, lw + pxu()*1.3, dl);
  c = mix(c, u_pal[5], line*mix(.2, .6, u_opt)*(.7 + .3*major));
  return c;
}

float washW(vec2 p, vec2 c, float r, float seed, float bleed){
  vec2 q = p + (.2 + .15*bleed)*vec2(fbm3(p*1.1 + seed), fbm3(p*1.1 + seed + 5.));
  vec2 v = rot(seed)*(q - c);
  return (r - length(v*vec2(.72, 1.25)))/r + .32*fbm(p*1.8 + seed*1.7);
}
void glaze(inout vec3 col, vec2 p, vec3 pig, vec3 paper, float f, float tooth, float seed){
  float inside = s01(-.01, .05, f);
  float edge = exp(-max(f, 0.)/.035)*inside;
  float dens = inside*(mix(.42, .62, u_dark) + .2*fbm3(vec2(f*3., seed))) + .45*edge;
  float gran = s01(.0, .8, gn(p/cssu()*.42 + seed*7.) + .6*gn(p/cssu()*.13 + seed));
  float floc = fbm3(p*7. + seed*3.);
  dens *= .72 + .32*tooth + .4*gran*mix(.6, 1., u_dark) + .18*floc;
  dens = sat(dens);
  col = vec3(col.x*mix(1., pig.x/paper.x, dens), col.yz + (pig.yz - paper.yz)*dens);
}
vec3 wall(vec2 p){
  vec3 paper = u_pal[5];
  float tooth = fbm3(p/cssu()*.07);
  vec3 col = paper;
  col.x += .012*tooth;
  float b = u_opt;
  glaze(col, p, u_pal[0], paper, washW(p, vec2(-.85, .35), .78, 1.3, b), tooth, 1.);
  glaze(col, p, u_pal[1], paper, washW(p, vec2(.55, .5), .62, 4.1, b), tooth, 2.);
  glaze(col, p, u_pal[2], paper, washW(p, vec2(.95, -.45), .7, 7.7, b), tooth, 3.);
  glaze(col, p, u_pal[3], paper, washW(p, vec2(-.2, -.55), .55, 9.2, b), tooth, 4.);
  glaze(col, p, u_pal[4], paper, washW(p, vec2(-1.45, -.7), .45, 12.5, b), tooth, 5.);
  return col;
}

float archD(vec2 p, vec2 c){ vec2 q = p - c; return q.y > 0. ? length(q) : abs(q.x); }
vec3 bandC(float k){
  vec3 c = u_pal[0];
  c = mix(c, u_pal[1], step(.5, k));
  c = mix(c, u_pal[2], step(1.5, k));
  c = mix(c, u_pal[3], step(2.5, k));
  return c;
}
void arches(inout vec3 col, vec2 p, vec2 c, float r0, float w, float rev){
  float d = archD(p, c);
  float outer = r0 + 4.*w;
  float sk = mix(.12, .4, u_opt);
  float dsh = archD(p - vec2(.03, -.045), c);
  float sh = (1. - s01(outer - .03, outer + .14, dsh))*s01(r0 - .12, r0 + .03, dsh);
  float a = cover(d - outer)*(1. - cover(d - r0));
  col = dim(col, sk*sh*(1. - a));
  float x = (d - r0)/w;
  float k = clamp(floor(x), 0., 3.);
  float f = fract(x);
  float kk = rev > .5 ? 3. - k : k;
  float kp = rev > .5 ? 4. - k : k - 1.;
  vec3 bc = bandC(kk);
  vec3 prev = bandC(clamp(kp, 0., 3.));
  bc = mix(prev, bc, k > .5 ? s01(0., pxu()*1.5/w, f) : 1.);
  bc = dim(bc, sk*.5*exp(-f/.07)*step(.5, k));
  bc.x += .02*(f - .5);
  col = mix(col, bc, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], dim(u_pal[5], .1), sat(.5 - p.y*.35));
  float sd = length(p - vec2(-.42, .5));
  col = mix(col, u_pal[4], cover(sd - .2));
  arches(col, p, vec2(.62, -.42), .2, .2, 0.);
  arches(col, p, vec2(-1.08, -.78), .1, .12, 1.);
  return col;
}

float sS(vec2 p){
  vec2 q = p*.9;
  q += .38*vec2(fbm3(q*.8), fbm3(q*.8 + 4.));
  return q.y*2.1 + .55*sin(q.x*1.25 + q.y*.8) + .28*fbm(q*1.2);
}
vec3 wall(vec2 p){
  float e = .003;
  float s = sS(p);
  vec2 g = vec2(sS(p + vec2(e, 0.)) - s, sS(p + vec2(0., e)) - s)/e;
  float bd = mix(.4, 1., u_opt);
  float rel = sin(s*7.)*.5 + sin(s*17. + 1.)*.2;
  vec3 c = ramp(.5 + .48*sin(s*1.15 + .3));
  c.x += bd*(.035*sin(s*7.) + .018*sin(s*17. + 1.) + .01*sin(s*41.));
  float gl = length(g);
  vec2 gd = g/max(gl, 1e-3);
  float sh = dot(gd, normalize(vec2(-.6, .8)))*cos(s*7.);
  c.x += .03*bd*sh;
  float groove = exp(-abs(fract(s*.6) - .5)*40.)*bd;
  c = mix(c, u_pal[5], .2*groove);
  c = dim(c, .1*s01(.5, 2.2, length(p*vec2(.7, 1.))));
  return c;
}

float drapeL(vec2 p){ return .55*sin(p.x*1.1 + .8*sin(p.y*.9 + 1.)) + .3*sin(p.x*2.3 - p.y*.6 + 2.) + .25*fbm3(p*.7 + 3.); }
vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .3*p.x - .3*p.y));
  c = mix(c, u_pal[2], .6*exp(-dot(p - vec2(-1.1, .9), p - vec2(-1.1, .9))*.35));
  c = mix(c, u_pal[3], .35*s01(.8, 2.4, length(p - vec2(-.4, .4))));
  float e = .01;
  float h = drapeL(p);
  vec2 gd = vec2(drapeL(p + vec2(e, 0.)) - h, drapeL(p + vec2(0., e)) - h)/e;
  c.x += .045*dot(gd, normalize(vec2(-.6, .8)));
  vec2 q = p/cssu();
  float per = mix(3.6, 6.5, u_opt);
  float tx = q.x/per + .35*gn(vec2(q.y*.006 + .29, 1.41)), ty = q.y/per + .35*gn(vec2(2.37, q.x*.006 + .61));
  float ix = floor(tx), iy = floor(ty);
  float fx = abs(fract(tx) - .5)*2., fy = abs(fract(ty) - .5)*2.;
  float twx = .5 + .42*s01(-.3, .7, gn(vec2(ix*.71 + .37, q.y*.018 + .53))), twy = .5 + .42*s01(-.3, .7, gn(vec2(q.x*.018 + .53, iy*.71 + .37)));
  float wx = 1. - s01(twx*.7, twx, fx), wy = 1. - s01(twy*.7, twy, fy);
  float over = mod(ix + iy, 2.);
  float top = mix(wy, wx, over);
  float gap = (1. - wx)*(1. - wy);
  float idv = .5*(h21(vec2(ix, 3.)) + h21(vec2(7., iy))) - .5;
  float k = mix(1., .85, u_dark);
  c.x += k*(.022*(top - .5) - .035*gap + .022*idv + .012*(twx + twy - 1.));
  c.x += .006*fbm3(p*3.);
  return c;
}

float fibreW(vec2 q, float a, float s){
  vec2 r = rot(a)*q;
  float v = gn(vec2(r.x*.01, r.y*.16) + s) + .4*gn(vec2(r.x*.03, r.y*.3) + s*2.);
  return exp(-abs(v)*10.)*s01(-.2, .6, gn(r*.008 + s*3.));
}
vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .25*p.x - .35*p.y));
  c = mix(c, u_pal[2], .5*exp(-dot(p - vec2(-.9, .8), p - vec2(-.9, .8))*.4));
  float form = fbm(p*2.6 + 4.);
  c.x += .026*form;
  c.yz *= 1. + .12*form;
  vec2 q = p/cssu();
  float fb = fibreW(q, .3, 1.) + fibreW(q, -.9, 7.) + fibreW(q, 1.6, 13.) + .7*fibreW(q*1.6, 2.4, 21.);
  float k = mix(.5, 1.4, u_opt)*mix(1., .75, u_dark);
  c.x += .04*sat(fb)*k;
  c.x += .004*gn(q*.08);
  vec2 cl = floor(q/70.);
  vec2 cp = (cl + .2 + .6*h22(cl + 5.))*70.;
  vec2 dq = rot(h21(cl + 2.)*6.28)*(q - cp);
  float fl = exp(-dot(dq*vec2(.3, 1.2), dq*vec2(.3, 1.2))/(2. + 6.*h21(cl + 8.)));
  c = mix(c, dim(u_pal[3], .2), fl*step(.62, h21(cl + 3.3))*.4*mix(.5, 1., u_opt));
  float fd = dot(p, normalize(vec2(.94, .34))) - .35;
  float side = s01(-.005, .005, fd);
  c.x += .016*side - .008;
  c.x += .025*exp(-abs(fd)/.012)*(1. - side) - .02*exp(-abs(fd)/.035)*side;
  c = mix(c, u_pal[3], .25*s01(.9, 2.3, length(p)));
  return c;
}

vec3 wall(vec2 p){
  float hz = -.22;
  float t = sat((p.y - hz)/1.2);
  vec3 c = mix(u_pal[2], u_pal[1], sm1(t*2.2));
  c = mix(c, u_pal[0], sm1(t*1.5 - .4));
  vec2 sp = vec2(.38, hz + .04);
  float g = mix(.35, .85, u_opt);
  c = mix(c, u_pal[4], g*(.55*exp(-length((p - sp)*vec2(.55, 1.))*2.6) + .35*exp(-length(p - sp)*9.)));
  if (p.y < hz) {
    float dy = hz - p.y;
    vec3 s = mix(u_pal[3], u_pal[5], sm1(dy/.8));
    s = mix(s, mix(u_pal[2], u_pal[1], .3), .45*exp(-dy*5.));
    float col_ = exp(-abs(p.x - sp.x)*(2.2 + dy*3.))*exp(-dy*2.2);
    float st = .5 + .5*gn(vec2(p.x*3., p.y*55./(dy + .3)));
    s = mix(s, u_pal[4], g*.55*col_*(.6 + .4*st));
    s.x += .006*gn(vec2(p.x*2., p.y*40./(dy + .2)));
    c = mix(c, s, cover(p.y - hz));
  }
  return c;
}

void disc(inout vec3 col, vec2 p, vec2 c, float r, vec3 dc, float sk){
  float d = length(p - c) - r;
  float ds = length(p - c - vec2(.06, -.09)*sk*2.) - r;
  float sh = 1. - s01(-.05, .35*sk + .05, ds);
  float a = cover(d);
  col = dim(col, mix(.1, .18, u_dark)*sh*(1. - a)*sk*1.6);
  vec3 b = dc;
  b.x += .025*dot(normalize(p - c + 1e-4), vec2(-.6, .8))*s01(-.4, 0., d);
  b.x += .012*exp(-abs(d)/.015);
  col = mix(col, b, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[0], u_pal[5], sm1(.5 - .25*p.x - .35*p.y));
  col = mix(col, u_pal[4], .4*exp(-dot(p - vec2(-1.2, .9), p - vec2(-1.2, .9))*.4));
  float sk = mix(.25, 1., u_opt);
  disc(col, p, vec2(-.78, .42), .15, u_pal[3], sk*.6);
  disc(col, p, vec2(1.05, -1.0), 1.3, u_pal[1], sk);
  disc(col, p, vec2(1.05, -1.0), .82, u_pal[2], sk);
  return col;
}

float ridgeMi(float x, float i){
  return .15 - i*.32 + .14*fbm3(vec2(x*(.55 + .2*i) + i*5.3, i*2.)) + .05*sin(x*.8 + i);
}
vec3 wall(vec2 p){
  vec3 c = mix(u_pal[4], u_pal[0], sm1((p.y + .2)/1.2));
  c = mix(c, u_pal[5], .3*s01(-.3, 1., p.y));
  float m = mix(.08, .3, u_opt);
  for (int k = 0; k < 3; k++) {
    float i = float(k);
    float y = ridgeMi(p.x, i);
    float a = cover((p.y - y)*.6);
    float dep = max(y - p.y, 0.);
    vec3 r = mix(u_pal[1], u_pal[3], i/2.);
    float fade = s01(.0, m + .1*i, dep);
    r = mix(r, mix(u_pal[4], u_pal[0], .4), fade*.85);
    c = mix(c, r, a);
  }
  return c;
}

float stR(float an, float sd){ return 1. + .055*sin(an*2. + sd) + .032*sin(an*3. + sd*2.3) + .018*sin(an*5. + sd*1.7); }
void stone(inout vec3 col, vec2 p, vec2 c, vec2 rr, float a, vec3 sc, float sd, float sk){
  float m = min(rr.x, rr.y);
  vec2 q = rot(-a)*(p - c)/rr;
  float k = stR(atan(q.y, q.x), sd);
  float dn = length(q)/k;
  float d = (dn - 1.)*m;
  vec2 qs = rot(-a)*(p - c - vec2(.05, -.065)*sk)/rr;
  float ds = (length(qs)/stR(atan(qs.y, qs.x), sd) - 1.)*m;
  float soft = 1. - s01(-.07, .05 + .17*sk, ds);
  float cont = exp(-max(d, 0.)/.014);
  float aa = pxu()*1.4;
  float a2 = 1. - smoothstep(-aa, aa, d);
  col = dim(col, (mix(.16, .26, u_dark)*soft*(.45 + sk) + mix(.22, .3, u_dark)*cont)*(1. - a2));
  float z = pow(sat(1. - dn*dn), .5);
  vec3 n = normalize(vec3(rot(a)*(q/max(k, .5))*(m/rr)*1.6, z + .04));
  float kw = sat(dot(n, normalize(vec3(-.55, .62, .56)))*.62 + .38);
  kw = kw*kw*(3. - 2.*kw);
  vec3 b = vec3(sc.x*(.62 + .45*kw), sc.yz*(1. + .3*(1. - kw)));
  b.x -= .05*pow(1. - z, 3.)*(1. - kw*.6);
  b.x += .045*fbm3(q*2.3 + sd*3.) + .015*gn(q*7. + sd);
  b.yz *= .88 + .24*(.5 + .5*fbm3(q*1.5 + sd*5.));
  vec2 g = p/cssu();
  b.x += .045*s01(.62, .82, gn(g*.38 + sd*9.)) - .05*s01(.6, .85, gn(g*.31 + sd*4.));
  float vd = abs(dot(q, vec2(cos(sd*2.), sin(sd*2.))) - .25*sin(sd*3.) + .06*gn(q*3. + sd));
  b.x += .05*exp(-vd/.03)*step(.5, fract(sd*.37));
  b.x += .028*pow(sat(dot(n, normalize(vec3(-.3, .4, .87)))), 9.);
  b.x += .03*(1. - kw)*pow(1. - z, 2.);
  col = mix(col, b, a2);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[5], dim(u_pal[5], .07), sat(.5 - p.y*.3 + p.x*.1));
  col.x += .03*exp(-dot(p - vec2(-.7, .6), p - vec2(-.7, .6))*.4);
  vec2 g = p/cssu();
  col.x += .016*(h21(floor(g*.7)) - .5) + .008*gn(g*.12) + .006*sin(p.y*22. + 3.*gn(p*2.));
  float sk = mix(.3, 1., u_opt);
  stone(col, p, vec2(.18, .02), vec2(.42, .3), .3, u_pal[0], 1.3, sk);
  stone(col, p, vec2(.8, -.3), vec2(.28, .21), -.4, u_pal[1], 4.1, sk);
  stone(col, p, vec2(-.32, -.38), vec2(.24, .17), .9, u_pal[2], 7.4, sk);
  stone(col, p, vec2(.64, .44), vec2(.17, .13), -.2, u_pal[3], 2.6, sk);
  stone(col, p, vec2(1.2, .12), vec2(.13, .1), .6, u_pal[4], 9.9, sk);
  return col;
}

vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[5], sm1(.5 + .3*p.x - .3*p.y));
  vec2 o = vec2(.5, .02);
  vec2 q = p - o;
  float r = length(q);
  float an = atan(q.y, q.x);
  float t = .5 + .5*sin(an + .6);
  float u = .5 + .5*sin(an*2. - 1.1);
  vec3 rc = mix(mix(u_pal[1], u_pal[2], t), mix(u_pal[3], u_pal[4], t), u);
  float g = mix(.6, 1.15, u_opt);
  float ring = exp(-pow((r - .62)/.17, 2.));
  float core = exp(-pow((r - .62)/.05, 2.));
  c = mix(c, rc, sat(ring*.8*g));
  c.x += .03*core*g;
  c = mix(c, mix(u_pal[0], rc, .15), .5*exp(-r*r*6.)*(1. - ring));
  return c;
}

vec3 wall(vec2 p){
  float sf = mix(.35, .1, u_opt);
  vec2 q = p + .18*vec2(gn(p*.7 + 2.), gn(p*.7 + 9.));
  vec2 c0 = vec2(-1.1, .55), c1 = vec2(.2, .8), c2 = vec2(1.25, .35), c3 = vec2(-.4, -.65), c4 = vec2(.95, -.7);
  float w0 = 1./pow(dot(q - c0, q - c0) + sf, 2.), w1 = 1./pow(dot(q - c1, q - c1) + sf, 2.), w2 = 1./pow(dot(q - c2, q - c2) + sf, 2.);
  float w3 = 1./pow(dot(q - c3, q - c3) + sf, 2.), w4 = 1./pow(dot(q - c4, q - c4) + sf, 2.), w5 = .35;
  vec3 c = (u_pal[0]*w0 + u_pal[1]*w1 + u_pal[2]*w2 + u_pal[3]*w3 + u_pal[4]*w4 + u_pal[5]*w5)/(w0 + w1 + w2 + w3 + w4 + w5);
  return c;
}

vec3 wall(vec2 p){
  vec3 c = mix(u_pal[0], u_pal[1], sm1(.5 + .3*p.x + .25*p.y));
  c = mix(c, u_pal[3], .4*s01(.6, 2.4, length(p - vec2(-.2, .1))));
  float pl = fbm(p/cssu()*.012) + .4*gn(p/cssu()*.06);
  c.x += .01*pl;
  vec2 o = vec2(-.15, .05);
  vec2 q = p - o;
  q = vec2(q.x - q.y*.42, q.y)*rot(.08);
  vec2 hs = vec2(.62, .5);
  float bl = .01 + .05*sat(.5 - q.y*.8);
  float win = s01(-hs.x - bl, -hs.x + bl, q.x)*s01(hs.x + bl, hs.x - bl, q.x)*s01(-hs.y - bl, -hs.y + bl, q.y)*s01(hs.y + bl, hs.y - bl, q.y);
  float mw = .035;
  float mull = s01(mw - bl, mw + bl, abs(q.x))*s01(mw*.8 - bl, mw*.8 + bl, abs(q.y + .05));
  float lv = mix(0., .75, u_opt);
  vec2 lq = q*2.2 + vec2(3., 1.);
  float leaf = s01(.05, .3, fbm(lq + .4*vec2(gn(lq*1.7), gn(lq*1.7 + 3.))))*s01(.0, .5, q.x + q.y*.6 + .3);
  float I = win*mull*(1. - lv*leaf*(.6 + .4*s01(.0, .5, bl*10.)));
  c = mix(c, u_pal[2], sat(I)*mix(.55, .6, u_dark));
  c.x += mix(.02, .035, u_dark)*I;
  return c;
}

void sheet(inout vec3 col, vec2 p, vec2 c, float R, vec3 sc, float dk){
  float d = length(p - c) - R;
  float ds = length(p - c - vec2(.03, -.05)*dk) - R;
  float sh = 1. - s01(-.04, .1 + .14*dk, ds);
  float a = cover(d);
  col = dim(col, mix(.09, .16, u_dark)*sh*(1. - a)*(.4 + dk));
  vec3 b = mix(sc, col, .18);
  b.x += .01*exp(-abs(d)/.012);
  col = mix(col, b, a);
}
vec3 wall(vec2 p){
  vec3 col = mix(u_pal[0], u_pal[5], sm1(.5 + .3*p.x - .3*p.y));
  float dk = mix(.2, 1., u_opt);
  sheet(col, p, vec2(-2.6, 2.3), 2.55, u_pal[1], dk);
  sheet(col, p, vec2(3.2, 1.9), 3.0, u_pal[2], dk);
  sheet(col, p, vec2(-1.2, -3.1), 2.6, u_pal[3], dk);
  sheet(col, p, vec2(2.4, -2.9), 2.4, u_pal[4], dk);
  return col;
}
